using System;
using System.Collections.Generic;
using Impostors;
using Sandbox.Definitions;
using Sandbox.Game.Entities;
using Shared.Config;
using VRage.Game;
using VRage.ModAPI;
using VRage.Voxels;
using VRageMath;

namespace Shared.Impostors;

// Asteroids the clients don't have by themselves. Procedural asteroids nobody edited are
// generated by every client within its view distance, the rest the server replicates only to
// about ViewDistance/√3 (MyVoxelReplicable). Planets are drawn by the game from afar anyway.
public sealed class VoxelSource : ImpostorSource
{
    // Colors by the material's mined ore, the rest are stone. Stone is fitted to screenshots of
    // real asteroids from 8 directions (a neutral gray the 4 bit quantization keeps exact), the ores keep their hues at about the same brightness.
    private static readonly Dictionary<string, Vector3I> OreColors = new()
    {
        ["Stone"] = new Vector3I(170, 170, 170),
        ["Iron"] = new Vector3I(178, 144, 123),
        ["Nickel"] = new Vector3I(187, 180, 162),
        ["Cobalt"] = new Vector3I(128, 144, 183),
        ["Magnesium"] = new Vector3I(200, 200, 194),
        ["Silicon"] = new Vector3I(191, 191, 202),
        ["Silver"] = new Vector3I(204, 204, 208),
        ["Gold"] = new Vector3I(208, 174, 85),
        ["Platinum"] = new Vector3I(204, 208, 217),
        ["Uranium"] = new Vector3I(136, 166, 110),
        ["Ice"] = new Vector3I(200, 208, 217),
    };

    private static readonly Vector3I Stone = OreColors["Stone"];

    // Cells across the content at the coarsest level, at least
    private const int CoarsestCells = 6;

    private readonly IPluginConfig config;

    // Storage edits seen per voxel map, the signature of its entry
    private readonly Dictionary<long, int> edits = new();

    public VoxelSource(IPluginConfig config)
    {
        this.config = config;
    }

    public override ImpostorKind Kind => ImpostorKind.Voxel;

    public override void Scan(ImpostorRegistry registry)
    {
        foreach (var entity in MyEntities.GetEntities())
        {
            if (
                entity is not MyVoxelMap map
                || map.Closed
                || map.MarkedForClose
                || map.Storage == null
            )
                continue;

            if (!map.Save && !map.ContentChanged && !map.BeforeContentChanged)
                continue;

            if (!edits.ContainsKey(map.EntityId))
            {
                edits[map.EntityId] = 0;
                map.RangeChanged += (voxel, min, max, data) =>
                    edits[voxel.EntityId] = edits.TryGetValue(voxel.EntityId, out var n)
                        ? n + 1
                        : 1;
            }

            var entry = registry.Touch(map.EntityId, this);
            entry.Tag = map;
            entry.WorldMatrix = map.WorldMatrix;
            entry.WorldAabb = map.PositionComp.WorldAABB;
            entry.Velocity = Vector3.Zero;

            long signature = edits[map.EntityId];
            if (entry.Signature != signature)
            {
                entry.Signature = signature;
                entry.Stale = true;
            }
        }
    }

    public override string Describe(ImpostorEntry entry) =>
        entry.Tag is MyVoxelMap { Storage: not null } map
            ? $"voxels={map.Storage.Size.X}x{map.Storage.Size.Y}x{map.Storage.Size.Z} occlusion={config.AsteroidOcclusion}"
            : "";

    public override Func<byte[][]> PrepareBuild(ImpostorEntry entry)
    {
        if (entry.Tag is not MyVoxelMap map || map.Closed || map.Storage == null)
            return null;

        var storage = map.Storage;
        var size = storage.Size;
        var corner = (Vector3)
            Vector3D.Transform(map.PositionLeftBottomCorner, MatrixD.Invert(map.WorldMatrix));

        // Material colors by voxel material index, looked up on the game thread
        var colors = new Vector3I[256];
        for (var i = 0; i < colors.Length; i++)
        {
            var material = MyDefinitionManager.Static.GetVoxelMaterialDefinition((byte)i);
            colors[i] =
                material?.MinedOre != null && OreColors.TryGetValue(material.MinedOre, out var c)
                    ? c
                    : Stone;
        }

        var occluded = config.AsteroidOcclusion;
        return () => Build(storage, size, corner, colors, occluded);
    }

    private static byte[][] Build(
        IMyStorage storage,
        Vector3I size,
        Vector3 corner,
        Vector3I[] colors,
        bool occluded
    )
    {
        // The levels read from the storage, from 8 up to the first that reads single voxels;
        // levels 4 and 2 are downsampled from 8
        var shapes = new byte[ImpostorEntry.Lods.Length][];
        var first = Array.IndexOf(ImpostorEntry.Lods, (byte)8);
        var levels = new List<(int index, int voxelLod)>();
        for (var i = first; i < shapes.Length; i++)
        {
            // The coarsest voxel level of detail with at least this many voxels along the longest axis
            var voxelLod = Math.Max(
                0,
                (int)Math.Floor(Math.Log(size.AbsMax() / (double)ImpostorEntry.Lods[i], 2))
            );
            levels.Add((i, voxelLod));
            if (voxelLod == 0)
                break;
        }

        // Finest first, for the extent of the content. The coarsest level is pooled from voxels
        // two levels finer, a cell filled when at least half of them are: the game's own
        // coarse voxels were eroded there, and level 8 looked half as large as level 16. It
        // also gets at least CoarsestCells cells across a rock that is small for its storage.
        var extent = 0f;
        var data = new MyStorageData();
        CellVolume level8 = null;
        for (var k = levels.Count - 1; k >= 0; k--)
        {
            var (i, voxelLod) = levels[k];
            var cellSize = (float)(1 << voxelLod);
            var pooled = k == 0 && k < levels.Count - 1 && voxelLod > 0;
            if (pooled)
            {
                if (extent > 0)
                    cellSize = Math.Min(cellSize, extent / CoarsestCells);
                voxelLod = Math.Max(0, voxelLod - 2);
            }

            var voxels = Vector3I.Max(Vector3I.One, size >> voxelLod);
            var voxelSize = (float)(1 << voxelLod);
            data.Resize(voxels);
            storage.ReadRange(
                data,
                MyStorageDataTypeFlags.ContentAndMaterial,
                voxelLod,
                Vector3I.Zero,
                voxels - 1
            );

            var cells = Vector3I.Ceiling(new Vector3(size) / cellSize);
            var volume = new CellVolume(cells, cellSize, corner, ImpostorEntry.Lods[i]);
            var min = new Vector3I(int.MaxValue);
            var max = new Vector3I(int.MinValue);
            var p = Vector3I.Zero;
            for (p.Z = 0; p.Z < voxels.Z; p.Z++)
            for (p.Y = 0; p.Y < voxels.Y; p.Y++)
            for (p.X = 0; p.X < voxels.X; p.X++)
            {
                if (data.Content(ref p) <= MyVoxelConstants.VOXEL_ISO_LEVEL)
                    continue;
                volume.Add(
                    corner + (new Vector3(p) + 0.5f) * voxelSize,
                    colors[data.Material(ref p)]
                );
                min = Vector3I.Min(min, p);
                max = Vector3I.Max(max, p);
            }

            // A pooled cell is filled when at least half of its voxels are
            if (pooled)
                volume.DropBelow(
                    Math.Max(1, (int)Math.Round(Math.Pow(cellSize / voxelSize, 3) / 2))
                );
            if (extent == 0 && max.X >= min.X)
                extent = (max - min + 1).AbsMax() * voxelSize;
            shapes[i] = volume.ToShape(smooth: true, occluded);
            BuildTiming.Mark(ImpostorEntry.Lods[i], shapes[i]);
            if (i == first)
                level8 = volume;
        }

        // Far asteroids cover a few pixels, where only their color is left to see. A coarse
        // cell is filled when half of its 8 children are, which keeps the volume; a thin rock
        // that would vanish that way keeps every cell with a filled child.
        var coarse = level8;
        for (var i = first - 1; i >= 0 && coarse != null; i--)
        {
            var finer = coarse;
            coarse = finer.Downsample(ImpostorEntry.Lods[i], 4);
            shapes[i] = coarse.ToShape(smooth: true, occluded);
            if (shapes[i].Length <= Shape.HeaderSize)
            {
                coarse = finer.Downsample(ImpostorEntry.Lods[i], 1);
                shapes[i] = coarse.ToShape(smooth: true, occluded);
            }
            BuildTiming.Mark(ImpostorEntry.Lods[i], shapes[i]);
        }
        return shapes;
    }
}
